import { generatePageFromInputs } from '@/utils/nocodeGenerator'

// 通过后端代理调用大模型，避免浏览器直连 DeepSeek 时的 CORS/预检问题
export async function generateNoCodePage (payload) {
  const safePayload = payload || {}
  try {
    const res = await fetch('/api/nocode/generate', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(safePayload)
    })
    const data = await res.json()
    if (res.ok && data && (data.html !== undefined || data.vueCode !== undefined)) {
      return {
        vueCode: data.vueCode || '',
        html: data.html || '',
        css: data.css || '',
        meta: data.meta || { provider: 'deepseek-chat' }
      }
    }
    // 接口返回非 2xx 或格式不对，记下错误信息，但仍用本地模板填充预览
    const errMsg = (data && data.message) ? data.message : (`HTTP ${res.status}`)
    console.warn('[nocode] 后端返回异常', res.status, errMsg, data && data.error)
    const local = generatePageFromInputs(safePayload)
    return {
      _fallback: true,
      _error: errMsg,
      _errorCode: data && data.error,
      vueCode: '',
      html: local.html,
      css: local.css,
      meta: { provider: 'local-template', ...(local.meta || {}) }
    }
  } catch (e) {
    console.warn('[nocode] 请求后端失败，使用本地模板', e)
  }
  const local = generatePageFromInputs(safePayload)
  return {
    _fallback: true,
    _error: (e && e.message) || '网络异常',
    vueCode: '',
    html: local.html,
    css: local.css,
    meta: { provider: 'local-template', ...(local.meta || {}) }
  }
}

function escapeHtml (str) {
  return String(str || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;')
}

function toSafeTextLines (text, maxLines) {
  const lines = String(text || '')
    .split('\n')
    .map(s => s.trim())
    .filter(Boolean)
  return lines.slice(0, maxLines)
}

// 这是一个“可替换的大模型生成器”：
// - 现在：基于上传图片（可选）+ 文字描述，生成一个合理的落地页骨架
// - 未来：把此处替换为后端大模型生成的 html/css 即可
export function generatePageFromInputs (input) {
  const title = (input && input.title) || '生成页面'
  const description = (input && input.description) || ''
  const images = (input && input.images) || []

  const bullets = toSafeTextLines(description, 8)
  const heroImage = images[0] && images[0].dataUrl ? images[0].dataUrl : ''

  const html = `
  <div class="nc-page">
    <div class="nc-hero">
      <div class="nc-hero-left">
        <div class="nc-title">${escapeHtml(title)}</div>
        <div class="nc-desc">${escapeHtml(description || '（未提供文字描述）')}</div>
        ${bullets.length
          ? `<ul class="nc-bullets">${bullets
              .map(b => `<li>${escapeHtml(b)}</li>`)
              .join('')}</ul>`
          : ''}
        <div class="nc-actions">
          <button class="nc-btn primary">立即开始</button>
          <button class="nc-btn">了解更多</button>
        </div>
      </div>
      <div class="nc-hero-right">
        ${
          heroImage
            ? `<img class="nc-hero-img" src="${heroImage}" alt="设计图" />`
            : `<div class="nc-hero-placeholder">未上传主视觉图片</div>`
        }
      </div>
    </div>

    ${
      images.length > 1
        ? `<div class="nc-gallery">
            <div class="nc-section-title">参考图片</div>
            <div class="nc-gallery-grid">
              ${images
                .slice(1, 7)
                .map(
                  img => `<div class="nc-gallery-item">
                    <img src="${img.dataUrl}" alt="${escapeHtml(img.name || '')}" />
                  </div>`
                )
                .join('')}
            </div>
          </div>`
        : ''
    }

    <div class="nc-section">
      <div class="nc-section-title">模块示例</div>
      <div class="nc-cards">
        <div class="nc-card">
          <div class="nc-card-title">模块 A</div>
          <div class="nc-card-text">根据描述自动生成的内容区块，可继续迭代为真实业务组件。</div>
        </div>
        <div class="nc-card">
          <div class="nc-card-title">模块 B</div>
          <div class="nc-card-text">未来接入大模型后，将输出更贴近 UI 设计稿的布局与样式。</div>
        </div>
        <div class="nc-card">
          <div class="nc-card-title">模块 C</div>
          <div class="nc-card-text">当前版本支持预览与保存，后续可扩展导出 Vue 文件/路由等。</div>
        </div>
      </div>
    </div>
  </div>
  `.trim()

  const css = `
  :root{
    --nc-bg: #f5f7fa;
    --nc-card: #ffffff;
    --nc-text: #1f1f1f;
    --nc-sub: #6b7280;
    --nc-border: rgba(0,0,0,.08);
    --nc-primary: #1677ff;
  }

  html,body{ height:100%; }
  body{
    margin:0;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Noto Sans", sans-serif;
    background: var(--nc-bg);
    color: var(--nc-text);
  }

  .nc-page{
    padding: 20px;
  }

  .nc-hero{
    display:flex;
    gap: 18px;
    align-items: stretch;
    background: var(--nc-card);
    border: 1px solid var(--nc-border);
    border-radius: 12px;
    padding: 18px;
    box-shadow: 0 2px 10px rgba(0,0,0,.04);
  }

  .nc-hero-left{
    flex: 1;
    min-width: 0;
  }

  .nc-title{
    font-size: 22px;
    font-weight: 700;
    margin-bottom: 10px;
  }

  .nc-desc{
    color: var(--nc-sub);
    line-height: 1.6;
    font-size: 14px;
    margin-bottom: 10px;
    white-space: pre-wrap;
  }

  .nc-bullets{
    padding-left: 18px;
    margin: 8px 0 12px;
    color: var(--nc-sub);
    font-size: 13px;
    line-height: 1.7;
  }

  .nc-actions{
    display:flex;
    gap: 10px;
    margin-top: 10px;
  }

  .nc-btn{
    border: 1px solid var(--nc-border);
    background: #fff;
    color: var(--nc-text);
    padding: 8px 14px;
    border-radius: 8px;
    cursor:pointer;
    font-size: 13px;
  }

  .nc-btn.primary{
    background: var(--nc-primary);
    border-color: var(--nc-primary);
    color: #fff;
  }

  .nc-hero-right{
    width: 46%;
    min-width: 320px;
    display:flex;
    align-items:center;
    justify-content:center;
  }

  .nc-hero-img{
    width: 100%;
    height: 260px;
    object-fit: cover;
    border-radius: 10px;
    border: 1px solid var(--nc-border);
    background: #fff;
  }

  .nc-hero-placeholder{
    width: 100%;
    height: 260px;
    border-radius: 10px;
    border: 1px dashed var(--nc-border);
    display:flex;
    align-items:center;
    justify-content:center;
    color: var(--nc-sub);
    background: #fafafa;
    font-size: 13px;
  }

  .nc-section{
    margin-top: 16px;
    background: var(--nc-card);
    border: 1px solid var(--nc-border);
    border-radius: 12px;
    padding: 16px 18px;
  }

  .nc-section-title{
    font-size: 16px;
    font-weight: 700;
    margin-bottom: 12px;
  }

  .nc-cards{
    display:grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 12px;
  }

  .nc-card{
    border: 1px solid var(--nc-border);
    border-radius: 10px;
    padding: 12px;
    background: #fff;
  }

  .nc-card-title{
    font-weight: 700;
    margin-bottom: 6px;
  }

  .nc-card-text{
    color: var(--nc-sub);
    font-size: 13px;
    line-height: 1.6;
  }

  .nc-gallery{
    margin-top: 16px;
    background: var(--nc-card);
    border: 1px solid var(--nc-border);
    border-radius: 12px;
    padding: 16px 18px;
  }

  .nc-gallery-grid{
    display:grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 10px;
  }

  .nc-gallery-item{
    border-radius: 10px;
    border: 1px solid var(--nc-border);
    overflow: hidden;
    background: #fff;
  }

  .nc-gallery-item img{
    width: 100%;
    height: 140px;
    object-fit: cover;
    display:block;
  }

  @media (max-width: 980px){
    .nc-hero{ flex-direction: column; }
    .nc-hero-right{ width: 100%; min-width: 0; }
    .nc-cards{ grid-template-columns: 1fr; }
    .nc-gallery-grid{ grid-template-columns: 1fr; }
  }
  `.trim()

  return {
    html,
    css,
    meta: {
      generator: 'local-fallback',
      version: 1
    }
  }
}

const puppeteer = require('puppeteer-core');

(async () => {
  const browser = await puppeteer.launch({
    executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
    headless: true,
    args: ['--no-sandbox', '--disable-gpu']
  });
  const page = await browser.newPage();
  await page.setViewport({ width: 1280, height: 800 });
  page.on('console', m => console.log('[console]', m.type(), m.text()));
  page.on('pageerror', e => console.log('[pageerror]', e.message));

  await page.goto('http://localhost:8081/river-city', { waitUntil: 'networkidle2', timeout: 30000 });
  await page.waitForTimeout(1000);

  // 点击开始游戏
  const clicked = await page.evaluate(() => {
    const btns = [...document.querySelectorAll('button')];
    const start = btns.find(b => b.textContent.includes('开始游戏') || b.textContent.trim() === '开始');
    if (start) { start.click(); return true; }
    return false;
  });
  console.log('clicked start:', clicked);
  await page.waitForTimeout(1500);

  // 读取 canvas 像素，统计关键颜色
  const result = await page.evaluate(() => {
    const canvas = document.querySelector('canvas');
    if (!canvas) return { error: 'no canvas' };
    const ctx = canvas.getContext('2d');
    const { width, height } = canvas;
    const img = ctx.getImageData(0, 0, width, height).data;
    const counts = { playerBlue: 0, enemyOrange: 0, bossRed: 0, skin: 0, hair: 0 };
    for (let i = 0; i < img.length; i += 4) {
      const r = img[i], g = img[i + 1], b = img[i + 2];
      // 玩家蓝 #1e88e5
      if (Math.abs(r - 0x1e) < 30 && Math.abs(g - 0x88) < 30 && Math.abs(b - 0xe5) < 30) counts.playerBlue++;
      // 敌人橙 #fb8c00
      if (Math.abs(r - 0xfb) < 30 && Math.abs(g - 0x8c) < 30 && Math.abs(b - 0x00) < 30) counts.enemyOrange++;
      // 头目红 #e53935
      if (Math.abs(r - 0xe5) < 30 && Math.abs(g - 0x39) < 30 && Math.abs(b - 0x35) < 30) counts.bossRed++;
      // 皮肤 #ffcc80
      if (Math.abs(r - 0xff) < 30 && Math.abs(g - 0xcc) < 30 && Math.abs(b - 0x80) < 30) counts.skin++;
      // 头发 #263238
      if (Math.abs(r - 0x26) < 30 && Math.abs(g - 0x32) < 30 && Math.abs(b - 0x38) < 30) counts.hair++;
    }
    return { width, height, counts };
  });
  console.log('canvas result:', JSON.stringify(result, null, 2));

  await browser.close();
})().catch(e => { console.error('FATAL', e); process.exit(1); });

